SELECT COUNT(*) bad FROM policy p JOIN (SELECT policy_id, MIN(inception_date) mi FROM policy_term GROUP BY 1) t USING(policy_id) WHERE t.mi <> p.first_inception;
SELECT SUM(pt.written_premium) total_all, SUM(CASE WHEN pt.txn_type='NEW' THEN 0 ELSE 0 END) x, COUNT(DISTINCT p.policy_id) pols
FROM premium_txn pt JOIN policy_term t USING(term_id) JOIN policy p USING(policy_id)
WHERE p.first_inception BETWEEN '2022-01-01' AND '2022-12-31';
SELECT pt.txn_type, SUM(pt.written_premium) wp FROM premium_txn pt JOIN policy_term t USING(term_id) JOIN policy p USING(policy_id)
WHERE p.first_inception BETWEEN '2022-01-01' AND '2022-12-31' GROUP BY 1;
